using System;
using System.Text;

namespace March7thHoney.SourceGen;

/// <summary>
///     Builds one generated file. Indentation follows the blocks that are open, so an emitter reads like the
///     code it produces. Lines always end with <c>\n</c>: the output is the same on every platform.
/// </summary>
internal sealed class CodeWriter
{
    private readonly StringBuilder _text = new();
    private int _depth;

    public CodeWriter()
    {
        Line("// <auto-generated/>");
        Line("#nullable enable");
    }

    public void Line() => _text.Append('\n');

    public void Line(string line) => _text.Append(' ', _depth * 4).Append(line).Append('\n');

    /// <summary>Opens a braced block; disposing it closes the block with <paramref name="close" />.</summary>
    public IDisposable Block(string close = "}")
    {
        Line("{");
        _depth++;
        return new Scope(this, close);
    }

    /// <summary>Indents the lines written until it is disposed, for a statement that continues over several lines.</summary>
    public IDisposable Indent()
    {
        _depth++;
        return new Scope(this, null);
    }

    public override string ToString() => _text.ToString();

    private sealed class Scope(CodeWriter writer, string? close) : IDisposable
    {
        public void Dispose()
        {
            writer._depth--;
            if (close != null) writer.Line(close);
        }
    }
}
